def solve(data):
    capacity = data["capacity"]
    ops = data["ops"]

    if capacity == 0:
        return []

    cache = OrderedDict()
    result = []

    for op, key, value in ops:
        if op == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op == "get":
            result.append(cache.get(key, -1))

    return result

